import {addAtmosphere as createAtmosphere} from './atmosphere.js';
import {spatialBatches,SegmentIndex} from './spatial.js';
import {addSurfaceBatches} from './surface-batches.js';
import {nearJunction} from './road-model.js';
import * as T from 'three';
import {heightAt,drapeGeometry,roadHeight} from './terrain.js';
import {project,polygons,inside,metres} from './model.js';
export function roadWidth(t){if(t.gameWidth>0)return t.gameWidth;const w=metres(t.width),n=parseFloat(t.lanes);return w>0?Math.min(50,w):n>0?Math.min(40,n*3.2):({motorway:20,trunk:17,primary:14,secondary:11,tertiary:9,residential:6,living_street:5,service:4,footway:1.8,path:1.5,pedestrian:5,steps:2,cycleway:2,stream:3,river:10})[t.highway||t.waterway]||5;}
export function roofHeight(t,h){return /^(gabled|hipped|pyramidal)$/.test(t['roof:shape'])?Math.min(h*.3,Math.max(1.2,metres(t['roof:height'])||2.5)):0;}
export function roofGeometry(poly,base,height,kind){if(!height)return null;const pts=poly.outer.slice(0,-1);let longest=0,u=[1,0];for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length],l=Math.hypot(b[0]-a[0],b[1]-a[1]);if(l>longest){longest=l;u=[(b[0]-a[0])/l,(b[1]-a[1])/l];}}const v=[-u[1],u[0]],us=pts.map(p=>p[0]*u[0]+p[1]*u[1]),vs=pts.map(p=>p[0]*v[0]+p[1]*v[1]),a=Math.min(...us),b=Math.max(...us),c=Math.min(...vs),d=Math.max(...vs),span=Math.max(.01,d-c);
 const y=p=>{const U=p[0]*u[0]+p[1]*u[1],V=p[0]*v[0]+p[1]*v[1];let h=Math.max(0,Math.min((V-c)/span,(d-V)/span)*2);if(kind!=='gabled')h=Math.min(h,Math.max(0,Math.min((U-a)/(b-a||1),(b-U)/(b-a||1))*2));return base+height*h;};
 const contour=pts.map(p=>new T.Vector2(...p)),holes=poly.holes.map(h=>h.slice(0,-1).map(p=>new T.Vector2(...p))),all=[...contour,...holes.flat()],tris=T.ShapeUtils.triangulateShape(contour,holes),pos=[];
 function triangle(a,b,c,depth){if(depth){const ab=[(a[0]+b[0])/2,(a[1]+b[1])/2],bc=[(b[0]+c[0])/2,(b[1]+c[1])/2],ca=[(c[0]+a[0])/2,(c[1]+a[1])/2];triangle(a,ab,ca,depth-1);triangle(ab,b,bc,depth-1);triangle(ca,bc,c,depth-1);triangle(ab,bc,ca,depth-1);return;}pos.push(a[0],y(a),a[1],c[0],y(c),c[1],b[0],y(b),b[1]);}
 for(const t of tris)triangle(...t.map(i=>[all[i].x,all[i].y]),3);
 for(const ring of [poly.outer,...poly.holes])for(let i=1;i<ring.length;i++){const A=ring[i-1],B=ring[i];for(let j=0;j<8;j++){const a=[A[0]+(B[0]-A[0])*j/8,A[1]+(B[1]-A[1])*j/8],b=[A[0]+(B[0]-A[0])*(j+1)/8,A[1]+(B[1]-A[1])*(j+1)/8];pos.push(a[0],base,a[1],a[0],y(a),a[1],b[0],y(b),b[1],a[0],base,a[1],b[0],y(b),b[1],b[0],base,b[1]);}}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.computeVertexNormals();g.setAttribute('uv',new T.Float32BufferAttribute(new Float32Array(pos.length/3*2),2));return g;}
export function laneGeometry(e){const t=e.tags,n=parseInt(t.lanes);if(t.gameArea||t.gameHidden)return null;if(!(n>=2&&n<=12)||!e.geometry||/footway|path|steps/.test(t.highway))return null;const ps=e.geometry.map(project),width=roadWidth(t),pos=[];let travel=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);if(!len)continue;for(let lane=1;lane<n;lane++){const off=-width/2+width*lane/n;for(let d=Math.ceil(travel/9)*9-travel;d<len;d+=9){const end=Math.min(d+3,len);if(end<=d||nearJunction(e,i,d,len)||nearJunction(e,i,end,len))continue;const x=a[0]+dx*d/len-dz/len*off,z=a[1]+dz*d/len+dx/len*off,X=a[0]+dx*end/len-dz/len*off,Z=a[1]+dz*end/len+dx/len*off,ox=-dz/len*.07,oz=dx/len*.07;pos.push(x+ox,.18,z+oz,x-ox,.18,z-oz,X+ox,.18,Z+oz,X+ox,.18,Z+oz,x-ox,.18,z-oz,X-ox,.18,Z-oz);}}travel+=len;}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));return g;}
export function compileAtmosphere(scene,data){const vegetation=new T.Group(),lamps=new T.Group();scene.add(vegetation,lamps);const trees=[],vine=[],land=new Map(),poles=[],heads=[];const dummy=new T.Object3D();
 function instances(group,g,mat,points){for(const chunk of spatialBatches(points)){const mesh=new T.InstancedMesh(g,mat,chunk.length);chunk.forEach((p,j)=>{dummy.position.set(p.p[0],p.p[1]+(p.base??heightAt(p.p[0],p.p[2])),p.p[2]);dummy.scale.set(...p.s);dummy.rotation.set(0,0,0);dummy.updateMatrix();mesh.setMatrixAt(j,dummy.matrix);});mesh.computeBoundingSphere();mesh.boundingSphere.radius+=6;mesh.matrixAutoUpdate=false;mesh.userData.detail=true;group.add(mesh);}}
 let seed=934;function rand(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}
 for(const e of data.green){for(const p of polygons(e)){const shape=new T.Shape(p.outer.map(p=>new T.Vector2(p[0],-p[1])));for(const h of p.holes)shape.holes.push(new T.Path(h.map(p=>new T.Vector2(p[0],-p[1]))));let g=new T.ShapeGeometry(shape);g.rotateX(-Math.PI/2);g.translate(0,.015,0);g=drapeGeometry(g,heightAt,60);const kind=e.tags.landuse||e.tags.natural;const color=kind==='meadow'?'#657c4d':kind==='vineyard'?'#637348':kind==='orchard'?'#536d43':'#2e513e';if(!land.has(color))land.set(color,[]);land.get(color).push(g);if(kind==='meadow')continue;const xs=p.outer.map(p=>p[0]),zs=p.outer.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),zmin=Math.min(...zs),zmax=Math.max(...zs);const spacing=kind==='vineyard'?16:kind==='orchard'?20:26;let budget=0;for(let x=xmin+spacing/2;x<xmax&&budget<1800;x+=spacing)for(let z=zmin+spacing/2;z<zmax&&budget<1800;z+=spacing){const xx=x+(kind==='forest'||kind==='wood'?(rand()-.5)*spacing*.7:0),zz=z+(kind==='forest'||kind==='wood'?(rand()-.5)*spacing*.7:0);if(!inside([xx,zz],p.outer)||p.holes.some(h=>inside([xx,zz],h)))continue;budget++;const h=kind==='vineyard'?1.6:kind==='orchard'?4:7+rand()*5;(kind==='vineyard'?vine:trees).push({p:[xx,h*.65,zz],s:[h*.4,h*.5,h*.4]});}}}
 for(const p of data.lampPoints||[]){const base=roadHeight(p.x,p.z,p.roadId);poles.push({p:[p.x,3.5,p.z],s:[.12,7,.12],base});heads.push({p:[p.x,7,p.z],s:[.75,.15,.4],base});}
 for(const [color,gs] of land)addSurfaceBatches(vegetation,gs,new T.MeshStandardMaterial({color,roughness:1,side:T.DoubleSide}));instances(vegetation,new T.CylinderGeometry(1,1,1,5),new T.MeshStandardMaterial({color:'#66513b'}),trees.map(t=>({p:[t.p[0],t.p[1]*.38,t.p[2]],s:[.18,t.p[1]*.77,.18]})));
 instances(vegetation,new T.IcosahedronGeometry(1,0),new T.MeshStandardMaterial({color:'#3d7048',roughness:1}),trees);instances(vegetation,new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#48663c'}),vine);instances(lamps,new T.CylinderGeometry(1,1,1,6),new T.MeshStandardMaterial({color:'#64716e'}),poles);const bulb=new T.MeshStandardMaterial({color:'#e1d8b4',emissive:'#ffca76',emissiveIntensity:.05});instances(lamps,new T.BoxGeometry(1,1,1),bulb,heads);
 // Distant billboard glows remain visible before local road illumination activates.
 const glow=new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,uniforms:{night:{value:0}},vertexShader:`varying vec2 vUv; varying float vDistance;
 void main(){vUv=uv;vec4 center=modelViewMatrix*instanceMatrix*vec4(0.,0.,0.,1.);vDistance=length(center.xyz);float size=clamp(vDistance*.003,2.8,7.);center.xy+=position.xy*size;gl_Position=projectionMatrix*center;}`,fragmentShader:`uniform float night;varying vec2 vUv;varying float vDistance;
 void main(){float r=length(vUv-.5)*2.;float halo=exp(-r*r*7.)*(1.-smoothstep(.75,1.,r));float fade=1.-smoothstep(1200.,1800.,vDistance);gl_FragColor=vec4(1.,.65,.25,halo*night*fade*.75);}`});
 instances(lamps,new T.PlaneGeometry(1,1),glow,heads.map(h=>({...h,s:[1,1,1]})));
 glow.userData.cityShader='glow';bulb.userData.cityShader='bulb';return {vegetation,lamps,heads,trees:trees.length};
}
export function addAtmosphere(scene,data){const baked=compileAtmosphere(scene,data);const materials=[];for(const m of baked.lamps.children)if(!materials.includes(m.material))materials.push(m.material);return createAtmosphere(scene,data,{...baked,materials});}
export {installRoadSurface} from './road-material.js';
